"""Disk layouts for the corpus, generated by script from the pinned files (B2).

A *disk* here is the list of candidates ADR 0027's enumeration would hand to the
model: the GPT partitions and the regular files of the ESP, to a depth of three
directories, each already turned into its 512-byte window (`window.py`). No image
is written: the bootloader's enumeration is not built yet (B3), so the candidates are
made from the same ingredients (the path as the firmware reports it, the first
bytes of the file) and the window function that B3 must reproduce.

The path of each file is taken from templates that follow the packaging of each
system (where Debian, Fedora, Alpine, openSUSE, OpenBSD and our own image put a
kernel, an initrd, a loader). That the templates are the author's reading of those
conventions, not paths copied from captured disks, is a limit of the corpus.

Labels that do not depend on the disk come from the asset (`catalogue.py`). The group
is the disk's own: the entries of a disk are numbered in a random order, 0 to 14,
and every candidate that belongs to no entry is group 15. That number is not a
function of the candidate, which is the finding of the group output (see the report).
"""
import random

import labels
import window

NO_ENTRY = labels.GROUPS - 1
MAX_ENTRIES = NO_ENTRY


class Candidate:
    __slots__ = ("window", "family", "protocol", "role", "group", "system", "release", "name", "entry", "disk",
                 "split", "path")

    def __init__(self, window_bytes, asset_labels, group, system, release, name, entry, disk, split, path=""):
        self.path = path
        self.window = window_bytes
        self.family, self.protocol, self.role = asset_labels
        self.group, self.system, self.release, self.name = group, system, release, name
        self.entry, self.disk, self.split = entry, disk, split

    def indices(self):
        return labels.encode(self.family, self.protocol, self.role, self.group)


class Entry:
    """A set of files that start together: a kernel with its initrd and device tree, or one loader."""

    def __init__(self, key):
        self.key = key
        self.files = []  # (path, asset)

    def add(self, path, asset):
        self.files.append((path, asset))
        return self


def hexname(rng, size=8):
    return "".join(rng.choice("0123456789abcdef") for _ in range(size))


def version(rng):
    return f"{rng.randrange(4, 7)}.{rng.randrange(0, 20)}.{rng.randrange(0, 200)}"


class Pool:
    """The assets of one split, indexed for the builders."""

    def __init__(self, assets):
        self.by_release = {}
        for a in assets:
            self.by_release.setdefault((a.system, a.release), {}).setdefault(a.name, []).append(a)
        self.by_system = {}
        for (system, release) in self.by_release:
            self.by_system.setdefault(system, []).append(release)
        for releases in self.by_system.values():
            releases.sort()

    def systems(self):
        return sorted(self.by_system)

    def release(self, rng, system):
        return rng.choice(self.by_system[system])

    def get(self, system, release, name):
        found = self.by_release[(system, release)].get(name)
        return found[0] if found else None

    def names(self, system, release):
        return sorted(self.by_release[(system, release)])

    def where(self, system, release, role):
        return [a for name in self.names(system, release) for a in self.by_release[(system, release)][name]
                if a.role == role]


def maybe_dtb(rng, entry, pool, system, release, folder, odds=0.25):
    dtbs = pool.where(system, release, "dtb")
    if dtbs and rng.random() < odds:
        dtb = rng.choice(dtbs)
        entry.add(f"{folder}\\{dtb.name}", dtb)


def alpine(rng, pool):
    release = pool.release(rng, "alpine")
    entries, extras = [], []
    flavours = [f for f in ("virt", "lts", "rpi") if pool.get("alpine", release, f"initramfs-{f}")]
    for flavour in rng.sample(flavours, rng.choice((1, 1, 2)) if len(flavours) > 1 else 1):
        kernel = pool.get("alpine", release, f"vmlinuz-{flavour}")
        initrd = pool.get("alpine", release, f"initramfs-{flavour}")
        style = rng.choice(("boot", "root", "short", "image"))
        folder, kname, iname = {
            "boot": ("\\boot", f"vmlinuz-{flavour}", f"initramfs-{flavour}"),
            "root": ("", f"vmlinuz-{flavour}", f"initramfs-{flavour}"),
            "short": ("", "VMLINUZ", "INITRD"),
            "image": ("\\boot", "Image", "initrd.img"),
        }[style]
        entry = Entry(("alpine", release, flavour))
        entry.add(f"{folder}\\{kname}", kernel).add(f"{folder}\\{iname}", initrd)
        maybe_dtb(rng, entry, pool, "alpine", release, f"{folder}\\dtbs-{flavour}")
        entries.append(entry)
        for prefix in ("config-", "System.map-", "modloop-"):
            if rng.random() < 0.4:
                found = [a for a in pool.where("alpine", release, "other")
                         if a.name.startswith(prefix) and a.name.endswith(flavour)]
                if found:
                    extras.append((f"{folder}\\{found[0].name}", found[0]))
    return entries, extras


def debian(rng, pool):
    release = pool.release(rng, "debian")
    kernel, initrd = pool.get("debian", release, "linux"), pool.get("debian", release, "initrd.gz")
    bootnet, grub = pool.get("debian", release, "bootnetaa64.efi"), pool.get("debian", release, "grubaa64.efi")
    entries, extras = [], []
    if rng.random() < 0.4:
        base = "\\debian-installer\\arm64"
        entry = Entry(("debian", release, "installer"))
        entry.add(f"{base}\\linux", kernel).add(f"{base}\\initrd.gz", initrd)
        entries.append(entry)
        if grub:
            entries.append(Entry(("debian", release, "grub-installer")).add(f"{base}\\grubaa64.efi", grub))
    else:
        v = f"{rng.randrange(4, 7)}.{rng.randrange(0, 20)}.{rng.randrange(0, 40)}-{rng.randrange(1, 9)}-arm64"
        entry = Entry(("debian", release, v))
        entry.add(f"\\boot\\vmlinuz-{v}", kernel).add(f"\\boot\\initrd.img-{v}", initrd)
        maybe_dtb(rng, entry, pool, "debian", release, f"\\usr\\lib\\linux-image-{v}", 0.2)
        entries.append(entry)
        if grub:
            entries.append(Entry(("debian", release, "grub")).add("\\EFI\\debian\\grubaa64.efi", grub))
        if bootnet:
            entries.append(Entry(("debian", release, "shim")).add(
                rng.choice(("\\EFI\\BOOT\\BOOTAA64.EFI", "\\EFI\\debian\\shimaa64.efi")), bootnet))
        for other in pool.where("debian", release, "other"):
            if rng.random() < 0.03:
                extras.append((f"\\EFI\\debian\\{rng.choice(('arm64-efi', 'fonts'))}\\{other.name}", other))
    return entries, extras


def el(rng, pool, system):
    release = pool.release(rng, system)
    kernel, initrd = pool.get(system, release, "vmlinuz"), pool.get(system, release, "initrd.img")
    tag = {"fedora": f"fc{release}", "alma": "el9", "rocky": "el9"}[system]
    v = f"{rng.randrange(5, 7)}.{rng.randrange(0, 20)}.{rng.randrange(0, 40)}-{rng.randrange(100, 600)}.{tag}.aarch64"
    entries, extras = [], []
    entry = Entry((system, release, v))
    if rng.random() < 0.5:
        entry.add(f"\\boot\\vmlinuz-{v}", kernel).add(f"\\boot\\initramfs-{v}.img", initrd)
    else:
        machine = "%032x" % rng.getrandbits(128)
        entry.add(f"\\{machine}\\{v}\\linux", kernel).add(f"\\{machine}\\{v}\\initrd", initrd)
        text_, _, _ = __import__("synthetic").bls_entry(rng, system)
        entry.add(f"\\loader\\entries\\{machine}-{v}.conf", _text_asset(system, release, text_))
    entries.append(entry)
    distro = {"fedora": "fedora", "alma": "almalinux", "rocky": "rocky"}[system]
    boot, grub = pool.get(system, release, "BOOTAA64.EFI"), pool.get(system, release, "grubaa64.efi")
    if boot:
        entries.append(Entry((system, release, "shim")).add("\\EFI\\BOOT\\BOOTAA64.EFI", boot))
        if rng.random() < 0.5:
            entries.append(Entry((system, release, "shim2")).add(f"\\EFI\\{distro}\\shimaa64.efi", boot))
    if grub:
        entries.append(Entry((system, release, "grub")).add(f"\\EFI\\{distro}\\grubaa64.efi", grub))
    for name in ("mmaa64.efi", "grub.cfg"):
        asset = pool.get(system, release, name)
        if asset and rng.random() < 0.6:
            extras.append((f"\\EFI\\{distro}\\{name}", asset))
    return entries, extras


def _text_asset(system, release, text_):
    import catalogue
    return catalogue.Asset(system, release, "entry.conf", text_, system_family(system), "linux", "entry", "", "synthetic")


def system_family(system):
    return "bsd" if system == "openbsd" else "linux"


def opensuse(rng, pool):
    release = pool.release(rng, "opensuse")
    kernel, initrd = pool.get("opensuse", release, "linux"), pool.get("opensuse", release, "initrd")
    entries = []
    if rng.random() < 0.6:
        v = f"{rng.randrange(5, 7)}.{rng.randrange(0, 12)}.0-{rng.randrange(100, 160)}.{rng.randrange(1, 50)}-default"
        entry = Entry(("opensuse", release, v))
        entry.add(f"\\boot\\vmlinuz-{v}", kernel).add(f"\\boot\\initrd-{v}", initrd)
    else:
        entry = Entry(("opensuse", release, "image"))
        entry.add("\\boot\\Image", kernel).add("\\boot\\initrd", initrd)
    entries.append(entry)
    return entries, []


def openbsd(rng, pool):
    release = pool.release(rng, "openbsd")
    entries = []
    loader = pool.get("openbsd", release, "BOOTAA64.EFI")
    entries.append(Entry(("openbsd", release, "boot")).add("\\EFI\\BOOT\\BOOTAA64.EFI", loader))
    for name in ("bsd", "bsd.mp", "bsd.rd"):
        kernel = pool.get("openbsd", release, name)
        if kernel and rng.random() < 0.7:
            entries.append(Entry(("openbsd", release, name)).add(f"\\{name}", kernel))
    return entries, []


def ours(rng, pool):
    kernels = [a for r in pool.by_system["ours"] for a in pool.where("ours", r, "kernel")]
    loaders = [a for r in pool.by_system["ours"] for a in pool.where("ours", r, "other")]
    kernel = rng.choice(kernels)
    entries = [Entry(("ours", kernel.release, "kernel")).add(
        rng.choice(("\\KERNEL.ELF", "\\kernel.elf", "\\boot\\kernel.elf", "\\sys\\KERNEL", "\\wsos\\kernel")), kernel)]
    extras = []
    if loaders:
        extras.append((rng.choice(("\\EFI\\BOOT\\BOOTAA64.EFI", "\\EFI\\wsos\\BOOTAA64.EFI")), rng.choice(loaders)))
    return entries, extras


BUILDERS = {
    "alpine": alpine, "debian": debian, "opensuse": opensuse, "openbsd": openbsd, "ours": ours,
    "fedora": lambda rng, pool: el(rng, pool, "fedora"),
    "alma": lambda rng, pool: el(rng, pool, "alma"),
    "rocky": lambda rng, pool: el(rng, pool, "rocky"),
}


def junk_paths(rng, name):
    return rng.choice((f"\\{name}", f"\\EFI\\{rng.choice(('tools', 'BOOT', 'shell'))}\\{name}",
                       f"\\docs\\{name}", f"\\backup\\old\\{name}", f"\\boot\\{name}"))


class Corpus:
    """The pieces disks are built from, for one split."""

    def __init__(self, assets, junk):
        import catalogue
        self.qemu = [a for a in assets if a.system == "qemu"]
        self.pool = Pool([a for a in assets if a.role != "other" or a.system not in ("alpine-rootfs",)])
        self.pool_systems = [s for s in self.pool.systems() if s in BUILDERS]
        self.rootfs = [a for a in assets if a.system == "alpine-rootfs"]
        self.others = [a for a in assets if a.system == "debian" and a.role == "other" and a.name.endswith(".mod")]
        self.junk = [catalogue.Asset("junk", kind, name, data, "none", "none", "other", "", "synthetic")
                     for kind, name, data in junk]


def make_disk(rng, corpus, disk_id, split, mode="normal"):
    systems = rng.choices([1, 2, 3, 0], weights=[45, 35, 15, 5])[0]
    chosen = rng.sample(corpus.pool_systems, min(systems, len(corpus.pool_systems)))
    entries, extras = [], []
    for system in chosen:
        e, x = BUILDERS[system](rng, corpus.pool)
        entries += e
        extras += x
    for _ in range(rng.choice((0, 0, 1, 2, 4, 6))):
        asset = rng.choice(corpus.junk + corpus.rootfs + corpus.others)
        extras.append((junk_paths(rng, asset.name), asset))
    if corpus.qemu and rng.random() < 0.15:
        asset = rng.choice(corpus.qemu)
        extras.append((f"\\boot\\dtb\\{asset.name}", asset))
    if mode == "renamed":
        entries = [_renamed(rng, e) for e in entries]
    entries, extras = without_repeated_paths(entries, extras)
    entries = entries[:MAX_ENTRIES]
    order = list(range(len(entries)))
    rng.shuffle(order)
    candidates = []
    for slot, entry in zip(order, entries):
        for path, asset in entry.files:
            candidates.append(_candidate(path, asset, slot, entry.key, disk_id, split))
    for path, asset in extras:
        candidates.append(_candidate(path, asset, NO_ENTRY, None, disk_id, split))
    if mode == "decoy":
        candidates += decoys(rng, corpus, disk_id, split)
    for name, guid, start in rng.sample(__import__("synthetic").PARTITIONS, rng.randrange(1, 4)):
        label = rng.choice(name)
        content = start(rng)
        candidates.append(Candidate(window.partition_window(label, guid, content), ("none", "none", "other"),
                                    NO_ENTRY, "partition", "", label, None, disk_id, split))
    rng.shuffle(candidates)
    return candidates


def without_repeated_paths(entries, extras):
    """A volume holds one file per path: an entry or file whose path is taken is dropped."""
    used, kept = set(), []
    for entry in entries:
        paths = [path.lower() for path, _ in entry.files]
        if len(set(paths)) == len(paths) and not used & set(paths):
            used |= set(paths)
            kept.append(entry)
    extras_kept = []
    for path, asset in extras:
        if path.lower() not in used:
            used.add(path.lower())
            extras_kept.append((path, asset))
    return kept, extras_kept


def _renamed(rng, entry):
    renamed = Entry(entry.key)
    for path, asset in entry.files:
        renamed.add(f"\\{hexname(rng)}{rng.choice(('.bin', '.dat', '', '.img'))}", asset)
    return renamed


def decoys(rng, corpus, disk_id, split):
    """Files that are not kernels but carry the names of one, the case a name-reading model gets wrong."""
    out = []
    for path in rng.sample(("\\vmlinuz", "\\boot\\vmlinuz-6.1.0-18-arm64", "\\initrd.img", "\\KERNEL.ELF",
                            "\\EFI\\BOOT\\BOOTAA64.EFI", "\\boot\\Image", "\\bsd", "\\grubaa64.efi"), rng.randrange(1, 4)):
        asset = rng.choice(corpus.junk + corpus.rootfs)
        out.append(_candidate(path, asset, NO_ENTRY, None, disk_id, split))
    return out


def _candidate(path, asset, slot, entry_key, disk_id, split):
    name = path.rsplit("\\", 1)[1]
    return Candidate(window.file_window(path, asset.content), asset.labels(), slot, asset.system, asset.release,
                     name, entry_key, disk_id, split, path)


def generate(assets, junk, split, count, seed, mode="normal", systems=None):
    """`count` disks of one split; `systems`, when given, limits the systems that carry boot entries."""
    rng = random.Random(seed)
    corpus = Corpus([a for a in assets if a.split == split], junk)
    if systems is not None:
        corpus.pool_systems = [s for s in corpus.pool_systems if s in systems]
    disks = []
    for disk_id in range(count):
        disks.append(make_disk(rng, corpus, f"{split}-{mode}-{disk_id}", split, mode))
    return disks
